def parse_args(argv):
    opts = {'scale':1.0, 'tabs':8, 'encoding':None, 'html':False, 'overwrite':False,
            'svg':False, 'svg_font_url':None, 'background':None, 'transparent':False,
            'no_shadows':False, 'debug':False, 'no_antialias':False,
            'no_separation':False, 'round_corners':False, 'verbose':False, 'fixed_slope':False,
            'order':[]}
    pos=[]; i=0
    if not argv:
        return opts,pos,'help_noargs',None
    while i < len(argv):
        a=argv[i]
        if a == '--help':
            return opts,pos,'help',None
        elif a in ('-A','--no-antialias'):
            opts['no_antialias']=True; opts['order'].append(('no-antialias',None)); i+=1
        elif a in ('-d','--debug'):
            opts['debug']=True; opts['order'].append(('debug',None)); i+=1
        elif a in ('-E','--no-separation'):
            opts['no_separation']=True; opts['order'].append(('no-separation',None)); i+=1
        elif a in ('-h','--html'):
            opts['html']=True; opts['order'].append(('html',None)); i+=1
        elif a in ('-o','--overwrite'):
            opts['overwrite']=True; opts['order'].append(('overwrite',None)); i+=1
        elif a in ('-r','--round-corners'):
            opts['round_corners']=True; opts['order'].append(('round-corners',None)); i+=1
        elif a in ('-S','--no-shadows'):
            opts['no_shadows']=True; opts['order'].append(('no-shadows',None)); i+=1
        elif a == '--svg':
            opts['svg']=True; opts['order'].append(('svg',None)); i+=1
        elif a in ('-T','--transparent'):
            opts['transparent']=True; opts['order'].append(('transparent',None)); i+=1
        elif a in ('-v','--verbose'):
            opts['verbose']=True; opts['order'].append(('verbose',None)); i+=1
        elif a in ('-W','--fixed-slope'):
            opts['fixed_slope']=True; opts['order'].append(('fixed-slope',None)); i+=1
        elif a in ('-b','--background','-e','--encoding','-s','--scale','-t','--tabs','--svg-font-url'):
            keymap={'-b':'background','--background':'background','-e':'encoding','--encoding':'encoding','-s':'scale','--scale':'scale','-t':'tabs','--tabs':'tabs','--svg-font-url':'svg_font_url'}
            key=keymap[a]
            if i+1>=len(argv):
                return opts,pos,'parse_error',f"Missing argument for option: {a}"
            val=argv[i+1]
            try:
                if key=='scale': opts[key]=float(val)
                elif key=='tabs': opts[key]=int(val)
                else: opts[key]=val
            except Exception:
                return opts,pos,'parse_error',f'Error: For input string: "{val}"'
            name={'background':'background','encoding':'encoding','scale':'scale','tabs':'tabs','svg_font_url':'svg-font-url'}[key]
            opts['order'].append((name,val)); i+=2
        elif a.startswith('-') and a != '-':
            return opts,pos,'parse_error',f"Unrecognized option: {a}"
        else:
            pos.append(a); i+=1
    if len(pos)<1:
        return opts,pos,'missing_input',None
    return opts,pos,'ok',None

def print_banner(opts):
    print()
    print(VERSION)
    print()
    print("Running with options:")
    for name,val in opts.get('order',[]):
        if val is None:
            print(name)
        else:
            print(f"{name} = {val}")

def expand_tabs(s, tab):
    out=[]; col=0
    for ch in s:
        if ch=='\t':
            n = tab - (col % tab)
            out.append(' '*n); col += n
        else:
            out.append(ch); col += 1
    return ''.join(out)

def read_text(path, opts):
    enc=opts.get('encoding') or 'utf-8'
    if path == '-':
        data=sys.stdin.buffer.read()
        try: return data.decode(enc)
        except Exception: return data.decode(enc, errors='replace')
    with open(path,'rb') as f: data=f.read()
    try: return data.decode(enc)
    except LookupError: raise
    except Exception: return data.decode(enc, errors='replace')

def normalize_grid(text, tabs=8):
    # ditaa strips a single final line break through normal line reading semantics
    lines=text.splitlines()
    lines=[expand_tabs(line, tabs) for line in lines]
    rows=len(lines); cols=max([len(l) for l in lines], default=0)
    grid=[list(l.ljust(cols)) for l in lines]
    return lines, grid, rows, cols

def base_dimensions(rows, cols):
    return cols*10 + 40, rows*14 + 56

def output_default(inp, svg=False):
    if inp == '-': return None
    root=inp
    if '.' in os.path.basename(root):
        root=os.path.splitext(root)[0]
    return root + ('.svg' if svg else '.png')

def choose_output_name(path, overwrite):
    if path is None or overwrite or not os.path.exists(path): return path
    base, ext = os.path.splitext(path)
    n=2
    while True:
        cand=f"{base}_{n}{ext}"
        if not os.path.exists(cand): return cand
        n += 1

def cell_center(c,r):
    return 25.0 + c*10.0, 35.0 + r*14.0

def is_corner(ch): return ch in '+*'
def hchar(ch): return ch in '-=+*<>:'
def vchar(ch): return ch in '|:+*^v'

def extract_diagram(text, opts):
    lines, grid, rows, cols = normalize_grid(text, opts.get('tabs',8))
    used=[[False]*cols for _ in range(rows)]
    shapes=[]
    if rows and cols:
        # Prefer largest rectangles so nested loops do not fragment too much.
        candidates=[]
        for r1 in range(rows):
            for c1 in range(cols):
                if not is_corner(grid[r1][c1]): continue
                for r2 in range(r1+1, rows):
                    if not vchar(grid[r2][c1]) and not is_corner(grid[r2][c1]): continue
                    if not is_corner(grid[r2][c1]): continue
                    for c2 in range(c1+1, cols):
                        if not (is_corner(grid[r1][c2]) and is_corner(grid[r2][c2])): continue
                        top=all(hchar(grid[r1][c]) for c in range(c1+1,c2))
                        bot=all(hchar(grid[r2][c]) for c in range(c1+1,c2))
                        left=all(vchar(grid[r][c1]) for r in range(r1+1,r2))
                        right=all(vchar(grid[r][c2]) for r in range(r1+1,r2))
                        if top and bot and left and right:
                            candidates.append((-(r2-r1)*(c2-c1),r1,c1,r2,c2))
        candidates.sort()
        occupied_rects=[]
        for _,r1,c1,r2,c2 in candidates:
            # Skip if same border already consumed by a larger rectangle.
            border=[(r1,c) for c in range(c1,c2+1)]+[(r2,c) for c in range(c1,c2+1)]+[(r,c1) for r in range(r1,r2+1)]+[(r,c2) for r in range(r1,r2+1)]
            if any(used[r][c] for r,c in border):
                continue
            inside='\n'.join(''.join(grid[r][c1+1:c2]) for r in range(r1+1,r2))
            tag=None
            for t in ('io','mo','tr','d','s','o','c'):
                if '{'+t+'}' in inside:
                    tag=t; break
            fill='white'
            for code,col in COLOR_CODES.items():
                if 'c'+code in inside:
                    fill=col
            dashed= any(grid[r][c1]==':' or grid[r][c2]==':' for r in range(r1+1,r2)) or any(grid[r1][c]=='=' or grid[r2][c]=='=' for c in range(c1+1,c2))
            points=[(r,c) for r,c in border if grid[r][c]=='*']
            shapes.append({'r1':r1,'c1':c1,'r2':r2,'c2':c2,'tag':tag,'fill':fill,'dashed':dashed,'points':points})
            for r,c in border: used[r][c]=True
            # mark markup inside as used
            for r in range(r1+1,r2):
                s=''.join(grid[r][c1+1:c2])
                for m in re.finditer(r'\{(?:io|mo|tr|[dsoc])\}|c(?:RED|GRE|BLU|PNK|YEL|BLK)', s):
                    for cc in range(c1+1+m.start(), c1+1+m.end()): used[r][cc]=True
    # connector lines not part of rectangles
    hlines=[]; vlines=[]; arrows=[]; points=[]
    for r in range(rows):
        c=0
        while c<cols:
            if not used[r][c] and grid[r][c] in '-=':
                c0=c
                while c<cols and not used[r][c] and grid[r][c] in '-=': c+=1
                if c-c0>=1:
                    dashed= any(grid[r][x]=='=' for x in range(c0,c))
                    x1,y=cell_center(c0,r); x2,_=cell_center(c-1,r)
                    hlines.append((x1,y,x2,y,dashed))
            else: c+=1
    for c in range(cols):
        r=0
        while r<rows:
            if not used[r][c] and grid[r][c] in '|:':
                r0=r
                while r<rows and not used[r][c] and grid[r][c] in '|:': r+=1
                if r-r0>=1:
                    dashed= any(grid[y][c]==':' for y in range(r0,r))
                    x,y1=cell_center(c,r0); _,y2=cell_center(c,r-1)
                    vlines.append((x,y1,x,y2,dashed))
            else: r+=1
    for r in range(rows):
        for c in range(cols):
            ch=grid[r][c]
            if ch=='*':
                x,y=cell_center(c,r); points.append((x,y)); used[r][c]=True
            if ch=='>':
                x,y=cell_center(c,r); arrows.append(('right',x,y)); used[r][c]=True
            elif ch=='<':
                x,y=cell_center(c,r); arrows.append(('left',x,y)); used[r][c]=True
            elif ch=='^':
                x,y=cell_center(c,r); arrows.append(('up',x,y)); used[r][c]=True
            elif ch=='v':
                x,y=cell_center(c,r); arrows.append(('down',x,y)); used[r][c]=True
    # Text: ignore ASCII line-art chars and consumed markup.
    text_items=[]
    structural=set('|-+=/\\:*<>^v')
    for r,line in enumerate(lines):
        chars=list(line.ljust(cols)) if cols else []
        # bullet transformation: " o text" -> "?text" at the o-column (original uses a bullet glyph that shows as ? in SVG text)
        s=''.join(chars)
        for m in re.finditer(r'(^| )o ([^|]+)', s):
            if m.group(1)==' ':
                idx=m.start()+1
                if idx<cols:
                    chars[idx]='?';
                    if idx+1<cols: chars[idx+1]=' '
        c=0
        while c<cols:
            if c<len(chars) and (not used[r][c]) and chars[c] not in structural and chars[c] != ' ':
                c0=c; buf=[]
                while c<cols and (not used[r][c]) and chars[c] not in structural:
                    buf.append(chars[c]); c+=1
                txt=''.join(buf).rstrip()
                # Drop markup remnants.
                txt=re.sub(r'\{(?:io|mo|tr|[dsoc])\}', '', txt)
                txt=re.sub(r'c(?:RED|GRE|BLU|PNK|YEL|BLK)', '', txt)
                if txt.strip() or txt.startswith('?'):
                    x=20+c0*10+2
                    y=28+r*14+12
                    fill='#000000'
                    # White text in dark colored shapes.
                    for sh in shapes:
                        if sh['r1']<r<sh['r2'] and sh['c1']<c0<sh['c2'] and sh['fill'] in ('#5555bb','#cc3333','#000000'):
                            fill='#ffffff'
                    text_items.append((x,y,txt,fill))
            else:
                c+=1
    return {'lines':lines,'grid':grid,'rows':rows,'cols':cols,'shapes':shapes,'hlines':hlines,'vlines':vlines,'arrows':arrows,'points':points,'texts':text_items}

def path_for_shape(sh, round_corners=False):
    x1,y1=cell_center(sh['c1'],sh['r1']); x2,y2=cell_center(sh['c2'],sh['r2'])
    tag=sh.get('tag')
    if tag=='d':
        mid=(x1+x2)/2
        return f"M{x1:.1f} {y1:.1f} L{x2:.1f} {y1:.1f} L{x2:.1f} {y2:.1f} Q{mid+10:.1f} {y2-5:.1f} {mid:.1f} {y2:.1f} Q{mid-10:.1f} {y2+5:.1f} {x1:.1f} {y2:.1f} z"
    if tag=='o':
        cx=(x1+x2)/2; cy=(y1+y2)/2; # cubic approximation matching original constants loosely
        return f"M{cx:.1f} {y1:.1f} C{x2:.1f} {y1:.1f} {x2:.1f} {cy:.1f} {x2:.1f} {cy:.1f} C{x2:.1f} {y2:.1f} {cx:.1f} {y2:.1f} {cx:.1f} {y2:.1f} C{x1:.1f} {y2:.1f} {x1:.1f} {cy:.1f} {x1:.1f} {cy:.1f} C{x1:.1f} {y1:.1f} {cx:.1f} {y1:.1f} {cx:.1f} {y1:.1f} z"
    if tag=='c':
        cx=(x1+x2)/2; cy=(y1+y2)/2
        return f"M{x1:.1f} {cy:.1f} L{cx:.1f} {y1:.1f} L{x2:.1f} {cy:.1f} L{cx:.1f} {y2:.1f} z"
    if tag=='io':
        return f"M{x1+5:.1f} {y1:.1f} L{x2+5:.1f} {y1:.1f} L{x2-5:.1f} {y2:.1f} L{x1-5:.1f} {y2:.1f} z"
    if tag=='mo':
        return f"M{x1:.1f} {y1:.1f} L{x2+10:.1f} {y1:.1f} L{x2:.1f} {y2:.1f} L{x1+10:.1f} {y2:.1f} z"
    if tag=='tr':
        return f"M{x1+10:.1f} {y1:.1f} L{x2-10:.1f} {y1:.1f} L{x2:.1f} {y2:.1f} L{x1:.1f} {y2:.1f} z"
    if tag=='s':
        return f"M{x1:.1f} {y1:.1f} C{x1+10:.1f} {y1+7:.1f} {x2-10:.1f} {y1+7:.1f} {x2:.1f} {y1:.1f} C{x2-10:.1f} {y1-7:.1f} {x1+10:.1f} {y1-7:.1f} {x1:.1f} {y1:.1f} M{x1:.1f} {y1:.1f} L{x1:.1f} {y2:.1f} C{x1+10:.1f} {y2+10:.1f} {x2-10:.1f} {y2+10:.1f} {x2:.1f} {y2:.1f} L{x2:.1f} {y1:.1f} "
    if round_corners:
        radx=5; rady=7
        return f"M{x1+radx:.1f} {y1:.1f} Q{x1:.1f} {y1:.1f} {x1:.1f} {y1+rady:.1f} L{x1:.1f} {y2-rady:.1f} Q{x1:.1f} {y2:.1f} {x1+radx:.1f} {y2:.1f} L{x2-radx:.1f} {y2:.1f} Q{x2:.1f} {y2:.1f} {x2:.1f} {y2-rady:.1f} L{x2:.1f} {y1+rady:.1f} Q{x2:.1f} {y1:.1f} {x2-radx:.1f} {y1:.1f} L{x1+radx:.1f} {y1:.1f} z"
    return f"M{x1:.1f} {y1:.1f} L{x1:.1f} {y2:.1f} L{x2:.1f} {y2:.1f} L{x2:.1f} {y1:.1f} z"

def svg_path(style, d):
    return f"    <path {style} d='{d}' />\n"

def render_svg(text, opts):
    d=extract_diagram(text, opts)
    bw,bh=base_dimensions(d['rows'], d['cols'])
    scale=opts.get('scale',1.0); w=int(round(bw*scale)); h=int(round(bh*scale))
    bg=background_svg(opts)
    font_family='Custom' if opts.get('svg_font_url') else 'Courier'
    out=[]
    out.append("<?xml version='1.0' encoding='UTF-8' standalone='no'?>\n")
