        out.append("    </filter>\n")
    out.append("  </defs>\n")
    if scale != 1.0:
        out.append("  <g stroke-width='1' stroke-linecap='square' stroke-linejoin='round' transform='scale(%s)'>\n" % (('%g'%scale)))
    else:
        out.append("  <g stroke-width='1' stroke-linecap='square' stroke-linejoin='round'>\n")
    out.append(f"    <rect x='0' y='0' width='{bw}' height='{bh}' style='fill: {bg}'/>{'' if not opts.get('transparent') else ''}\n")
    # arrowheads under lines, matching original ordering.
