        elif direc=='up': pd=f"M{x-5:.1f} {y+7:.1f} L{x:.1f} {y-7:.1f} L{x+5:.1f} {y+7:.1f} z"
        else: pd=f"M{x-5:.1f} {y-7:.1f} L{x:.1f} {y+7:.1f} L{x+5:.1f} {y-7:.1f} z"
        out.append(svg_path("stroke='none' stroke-width='1.0' stroke-linecap='round' stroke-linejoin='round' fill='#000000'", pd))
    # shadows for filled shapes
    if not opts.get('no_shadows'):
        for sh in d['shapes']:
            if not sh.get('dashed'):
                out.append(svg_path("stroke='gray' fill='gray' filter='url(#f2)'", path_for_shape(sh, opts.get('round_corners'))))
    for sh in d['shapes']:
        path=path_for_shape(sh, opts.get('round_corners'))
        if sh.get('dashed'):
            style="stroke='#000000' stroke-width='1.0' stroke-dasharray='5.0,5.0' stroke-miterlimit='0' stroke-linecap='butt' stroke-linejoin='round' fill='none'"
        elif sh.get('tag')=='s':
            # storage is rendered as a white-filled path plus an outline
            out.append(svg_path("stroke='white' stroke-width='1.0' stroke-linecap='round' stroke-linejoin='round' fill='%s'" % sh['fill'], path))
            style="stroke='#000000' stroke-width='1.0' stroke-linecap='round' stroke-linejoin='round' fill='none'"
        else:
            style="stroke='#000000' stroke-width='1.0' stroke-linecap='round' stroke-linejoin='round' fill='%s'" % sh['fill']
        out.append(svg_path(style, path))
        for rr,cc in sh.get('points',[]):
            x,y=cell_center(cc,rr)
            out.append(svg_circle_path(x,y))
    for x1,y1,x2,y2,dashed in d['hlines']+d['vlines']:
        style="stroke='#000000' stroke-width='1.0' " + ("stroke-dasharray='5.0,5.0' stroke-miterlimit='0' stroke-linecap='butt'" if dashed else "stroke-linecap='round'") + " stroke-linejoin='round' fill='none'"
        out.append(svg_path(style, f"M{x1:.1f} {y1:.1f} L{x2:.1f} {y2:.1f} "))
    for x,y in d['points']:
        out.append(svg_circle_path(x,y))
    for x,y,txt,fill in d['texts']:
        # Original often preserves one trailing space for one-character text; not critical but similar.
        cdata=txt.replace(']]>', ']]]]><![CDATA[>')
        out.append(f"    <text x='{int(x)}' y='{int(y)}' font-family='{font_family}' font-size='15' stroke='none' fill='{fill}' ><![CDATA[{cdata}]]></text>\n")
    out.append("  </g>\n")
    out.append("</svg>")
    return ''.join(out).encode('utf-8')

def svg_circle_path(x,y):
    return svg_path("stroke='#000000' stroke-width='1.0' stroke-linecap='round' stroke-linejoin='round' fill='#ffffff'", f"M{x+3.5:.1f} {y:.1f} C{x+3.5:.1f} {y+1.933:.3f} {x+1.933:.3f} {y+3.5:.1f} {x:.1f} {y+3.5:.1f} C{x-1.933:.3f} {y+3.5:.1f} {x-3.5:.1f} {y+1.933:.3f} {x-3.5:.1f} {y:.1f} C{x-3.5:.1f} {y-1.933:.3f} {x-1.933:.3f} {y-3.5:.1f} {x:.1f} {y-3.5:.1f} C{x+1.933:.3f} {y-3.5:.1f} {x+3.5:.1f} {y-1.933:.3f} {x+3.5:.1f} {y:.1f} z")

def background_rgba(opts):
    if opts.get('transparent'):
        return (0,0,0,0), True
    bg=opts.get('background')
    if bg:
        s=bg.strip().lstrip('#')
        try:
            if len(s)>=8:
                return (int(s[0:2],16),int(s[2:4],16),int(s[4:6],16),int(s[6:8],16)), True
            if len(s)>=6:
                return (int(s[0:2],16),int(s[2:4],16),int(s[4:6],16),255), False
        except Exception: pass
    return (255,255,255,255), False

def background_svg(opts):
    if opts.get('transparent'):
        return 'none'
    bg=opts.get('background')
    if bg:
        s=bg.strip().lstrip('#')
        if len(s)>=6: return '#'+s[:6].lower()
    return '#ffffff'

def hex_to_rgba(col):
    if col=='white': return (255,255,255,255)
    if col.startswith('#') and len(col)>=7:
        return (int(col[1:3],16),int(col[3:5],16),int(col[5:7],16),255)
    return (255,255,255,255)

class Canvas:
    def __init__(self,w,h,bg,alpha=False,scale=1.0):
        self.w=max(1,int(round(w*scale))); self.h=max(1,int(round(h*scale))); self.alpha=alpha; self.scale=scale
        self.pix=[ [bg for _ in range(self.w)] for __ in range(self.h) ]
    def tr(self,x,y): return int(round(x*self.scale)), int(round(y*self.scale))
    def set(self,x,y,col):
        if 0<=x<self.w and 0<=y<self.h:
            self.pix[y][x]=col
    def line(self,x1,y1,x2,y2,col,width=1):
        x1,y1=self.tr(x1,y1); x2,y2=self.tr(x2,y2); width=max(1,int(round(width*self.scale)))
        dx=abs(x2-x1); dy=-abs(y2-y1); sx=1 if x1<x2 else -1; sy=1 if y1<y2 else -1; err=dx+dy
        x,y=x1,y1
        while True:
            r=width//2
            for yy in range(y-r,y+r+1):
                for xx in range(x-r,x+r+1): self.set(xx,yy,col)
            if x==x2 and y==y2: break
            e2=2*err
            if e2>=dy: err+=dy; x+=sx
            if e2<=dx: err+=dx; y+=sy
    def rect_fill(self,x1,y1,x2,y2,fill,outline=(0,0,0,255)):
        ax,ay=self.tr(min(x1,x2),min(y1,y2)); bx,by=self.tr(max(x1,x2),max(y1,y2))
        for y in range(ay,by+1):
            for x in range(ax,bx+1): self.set(x,y,fill)
        self.line(x1,y1,x2,y1,outline); self.line(x2,y1,x2,y2,outline); self.line(x2,y2,x1,y2,outline); self.line(x1,y2,x1,y1,outline)
    def poly(self,pts,fill,outline=(0,0,0,255)):
        pts2=[self.tr(x,y) for x,y in pts]
        if fill is not None:
            miny=max(0,min(y for x,y in pts2)); maxy=min(self.h-1,max(y for x,y in pts2))
            for y in range(miny,maxy+1):
                xs=[]
                for i in range(len(pts2)):
                    x1,y1=pts2[i]; x2,y2=pts2[(i+1)%len(pts2)]
                    if y1==y2: continue
                    if (y>=min(y1,y2)) and (y<max(y1,y2)):
                        xs.append(int(round(x1+(y-y1)*(x2-x1)/(y2-y1))))
                xs.sort()
                for a,b in zip(xs[::2],xs[1::2]):
                    for x in range(max(0,a), min(self.w-1,b)+1): self.set(x,y,fill)
        for i in range(len(pts)):
            self.line(*pts[i], *pts[(i+1)%len(pts)], outline)
    def ellipse(self,x1,y1,x2,y2,fill,outline=(0,0,0,255)):
        ax,ay=self.tr(min(x1,x2),min(y1,y2)); bx,by=self.tr(max(x1,x2),max(y1,y2)); cx=(ax+bx)/2; cy=(ay+by)/2; rx=max(1,(bx-ax)/2); ry=max(1,(by-ay)/2)
        for y in range(max(0,ay), min(self.h-1,by)+1):
            for x in range(max(0,ax), min(self.w-1,bx)+1):
                v=((x-cx)/rx)**2+((y-cy)/ry)**2
                if v<=1.0: self.set(x,y,fill)
                if 0.85<=v<=1.15: self.set(x,y,outline)
    def circle(self,x,y,r,fill,outline=(0,0,0,255)):
        cx,cy=self.tr(x,y); rr=max(1,int(round(r*self.scale)))
        for yy in range(cy-rr,cy+rr+1):
            for xx in range(cx-rr,cx+rr+1):
                d=(xx-cx)**2+(yy-cy)**2
                if d<=rr*rr: self.set(xx,yy,fill)
                if abs(d-rr*rr)<=max(2,rr): self.set(xx,yy,outline)
    def text(self,x,y,txt,col):
        sx,sy=self.tr(x,y-11)
        sc=max(1,int(round(self.scale)))
        # fit font height close to 10 px at scale 1
        for i,ch in enumerate(txt):
            pat=FONT.get(ch, FONT.get(ch.upper(), [31,17,17,17,17,17,31]))
            ox=sx+i*7*sc
            for row,bits in enumerate(pat):
                for bit in range(5):
                    if bits & (1<<(4-bit)):
                        for yy in range(sc):
                            for xx in range(sc): self.set(ox+bit*sc+xx, sy+row*sc+yy, col)
    def png(self):
        color_type=6 if self.alpha else 2
        raw=[]
        for row in self.pix:
            raw.append(b'\x00')
            if self.alpha:
                raw.append(bytes([v for px in row for v in px]))
            else:
                raw.append(bytes([v for px in row for v in px[:3]]))
        data=b''.join(raw)
        def chunk(typ,payload):
            return struct.pack('>I',len(payload))+typ+payload+struct.pack('>I',binascii.crc32(typ+payload)&0xffffffff)
        ihdr=struct.pack('>IIBBBBB', self.w,self.h,8,color_type,0,0,0)
        return b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',ihdr)+chunk(b'IDAT',zlib.compress(data,9))+chunk(b'IEND',b'')

def render_png(text, opts):
    d=extract_diagram(text, opts)
    bw,bh=base_dimensions(d['rows'], d['cols'])
    bg,alpha=background_rgba(opts)
    c=Canvas(bw,bh,bg,alpha,opts.get('scale',1.0))
    black=(0,0,0,255); gray=(180,180,180,255)
    if opts.get('debug'):
        # light gray grid
        for x in range(20,bw,10): c.line(x,0,x,bh,(170,170,170,255))
        for y in range(28,bh,14): c.line(0,y,bw,y,(170,170,170,255))
    if not opts.get('no_shadows'):
        for sh in d['shapes']:
            if not sh.get('dashed'):
                x1,y1=cell_center(sh['c1'],sh['r1']); x2,y2=cell_center(sh['c2'],sh['r2'])
                c.rect_fill(x1+5,y1+5,x2+5,y2+5,gray,gray)
    for sh in d['shapes']:
        x1,y1=cell_center(sh['c1'],sh['r1']); x2,y2=cell_center(sh['c2'],sh['r2'])
        fill=hex_to_rgba(sh['fill'])
        tag=sh.get('tag')
        if sh.get('dashed'):
            fill=None
        if tag=='o': c.ellipse(x1,y1,x2,y2,fill or bg,black)
        elif tag=='c': c.poly([(x1,(y1+y2)/2),((x1+x2)/2,y1),(x2,(y1+y2)/2),((x1+x2)/2,y2)],fill or bg,black)
        elif tag=='io': c.poly([(x1+5,y1),(x2+5,y1),(x2-5,y2),(x1-5,y2)],fill or bg,black)
        elif tag=='mo': c.poly([(x1,y1),(x2+10,y1),(x2,y2),(x1+10,y2)],fill or bg,black)
        elif tag=='tr': c.poly([(x1+10,y1),(x2-10,y1),(x2,y2),(x1,y2)],fill or bg,black)
        else: c.rect_fill(x1,y1,x2,y2,fill or bg,black)
        for rr,cc in sh.get('points',[]):
            x,y=cell_center(cc,rr); c.circle(x,y,3.5,bg,black)
    for direc,x,y in d['arrows']:
        if direc=='right': pts=[(x-5,y-7),(x+5,y),(x-5,y+7)]
        elif direc=='left': pts=[(x+5,y-7),(x-5,y),(x+5,y+7)]
        elif direc=='up': pts=[(x-5,y+7),(x,y-7),(x+5,y+7)]
        else: pts=[(x-5,y-7),(x,y+7),(x+5,y-7)]
        c.poly(pts,black,black)
    for x1,y1,x2,y2,dashed in d['hlines']+d['vlines']:
        if dashed:
            # simple dash segments
            length=math.hypot(x2-x1,y2-y1); n=max(1,int(length//10));
            for i in range(n+1):
                if i%2==0:
                    a=i/n if n else 0; b=min(1,(i+0.5)/n) if n else 1
                    c.line(x1+(x2-x1)*a,y1+(y2-y1)*a,x1+(x2-x1)*b,y1+(y2-y1)*b,black)
        else: c.line(x1,y1,x2,y2,black)
    for x,y in d['points']: c.circle(x,y,3.5,bg,black)
    for x,y,txt,fill in d['texts']:
        c.text(x,y,txt,hex_to_rgba(fill))
    return c.png()

def write_file(path, data):
    try:
        with open(path,'wb') as f: f.write(data)
        return True
    except Exception:
        return False

def print_debug_grid(text, opts):
    lines, grid, rows, cols=normalize_grid(text, opts.get('tabs',8))
    # Observed grid has a two-character border of blanks around input.
    gcols=cols+4; grows=rows+4
    print("Using grid:")
    print("    " + ''.join(str(i%10) for i in range(gcols)))
    for r in range(grows):
        if r<10: prefix=f" {r} ("
        else: prefix=f"{r} ("
        if 2 <= r < rows+2:
            content='  '+lines[r-2].ljust(cols)+'  '
        else:
            content=' '*gcols
        print(prefix+content+")")

def process_render(inp, outp, opts, defaulted=False):
    if inp != '-' and not os.path.exists(inp):
        print_banner(opts)
        print(f"Reading file: {inp}")
        print(f"Error: File {inp} does not exist", file=sys.stderr)
        return 1
    try:
        text=read_text(inp, opts)
    except LookupError as e:
        print_banner(opts); print(f"Reading file: {inp}"); print(f"Error: {e}", file=sys.stderr); return 1
    # If stdin and no output file, the original emits raw image/svg to stdout only.
    if inp == '-' and outp is None:
        data=render_svg(text,opts) if opts.get('svg') else render_png(text,opts)
        sys.stdout.buffer.write(data)
        return 0
    print_banner(opts)
    if inp=='-': print("Reading standard input")
    else: print(f"Reading file: {inp}")
    if opts.get('debug'):
        print_debug_grid(text, opts)
    print(f"Rendering to file: {outp}")
    data=render_svg(text,opts) if opts.get('svg') else render_png(text,opts)
    if not write_file(outp,data):
        print(f"Error: Cannot write to file {outp}", file=sys.stderr)
        return 1
    print("Done in 0sec")
    return 0

def convert_html(inp, outp, opts):
    if inp != '-' and not os.path.exists(inp):
        print_banner(opts); print(f"Error: File {inp} does not exist", file=sys.stderr); return 1
    if outp is None:
        root=os.path.splitext(inp)[0]
        outp=root+'_processed.html'
    if os.path.exists(outp) and not opts.get('overwrite'):
        print_banner(opts)
        print(f"Error: File {outp} exists. If you would like to overwrite it, please use the --overwrite option.")
        return 0
    text=read_text(inp, opts)
    diagrams=[]; counter=1
    # loose pre-tag parser; id may appear before/after class.
    def repl(m):
        nonlocal counter
        attrs=m.group(1); body=m.group(2)
        idm=re.search(r'id\s*=\s*["\']([^"\']+)["\']', attrs, re.I)
        if idm: name=idm.group(1)
        else:
            name=f"ditaa_diagram_{counter}"; counter+=1
        body=html.unescape(body)
        diagrams.append((name,body))
        return f'<img src="images/{name}.png" />'
    processed=re.sub(r'<pre\b([^>]*)class\s*=\s*["\'][^"\']*textdiagram[^"\']*["\'][^>]*>(.*?)</pre>', repl, text, flags=re.I|re.S)
    print_banner(opts)
    print(f"Converting HTML file ({inp} -> {outp})...", end=' ')
    ok=write_file(outp, processed.encode(opts.get('encoding') or 'utf-8', errors='replace'))
    if not ok:
        print('')
        print(f"Error: Cannot write to file {outp}", file=sys.stderr); return 1
    print("done")
    print("Generating diagrams... ")
    # The observed executable attempts mkdir and treats an existing or uncreatable directory as failure.
    try:
        os.mkdir('images')
    except Exception:
        print("Could not create directory images", file=sys.stderr)
        return 0
    for name,body in diagrams:
        path=os.path.join('images',name+'.png')
        if os.path.exists(path) and not opts.get('overwrite'):
            continue
        write_file(path, render_png(body, opts))
    print("Done in 0sec")
    return 0

def main(argv):
    opts,pos,status,msg=parse_args(argv)
    if status in ('help_noargs','help'):
        sys.stdout.write(HELP_UPPER); return 0
    if status=='parse_error':
        sys.stdout.write(HELP_UPPER)
        if msg:
            # Commons CLI-like parse errors are stderr without an added prefix except our conversion errors.
            print(msg, file=sys.stderr)
        return 2
    if status=='missing_input':
        sys.stdout.write(HELP_LOWER)
        print("Error: Please provide the input file filename", file=sys.stderr)
        return 2
    inp=pos[0]
    explicit_out = len(pos)>=2
    outp=pos[1] if explicit_out else output_default(inp, opts.get('svg'))
    if opts.get('html'):
        return convert_html(inp, outp if explicit_out else None, opts)
    if not explicit_out:
        outp=choose_output_name(outp, opts.get('overwrite'))
    return process_render(inp,outp,opts,defaulted=not explicit_out)

if __name__=='__main__':
    sys.exit(main(sys.argv[1:]))
